/**
 * Kommunikation & samspel → Åsikter & argument, 1111–1117 (0.29): expressing an opinion, agreeing and
 * objecting, giving reasons, comparing alternatives, cause and consequence, weighing evidence and
 * changing one's mind. Nearly every word is abstract, so the pictures are small symbolic scenes:
 * speech bubbles with icons (never words), checks and crosses for yes and no, documents and charts
 * for facts, scales for weighing, arrows for causes, and a grey reference where a contrast helps.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { type Build } from './figures';
import { HL, T, arm, heart, cloud, sun, cup, thought, crossedArms, envelope, bolt, padlock, cat } from './people';
import { P as F, type Mood, greyed, coin } from './blindFix';
import { checkIcon, bikeIcon } from './labelIcons';

// ── Geometry and figures ─────────────────────────────────────────────
const RED = '#e8302c';
const f1 = (n: number) => n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
/** Head and shoulder positions of a standing figure (figures.ts) at x with height factor h. */
const geo = (x: number, h = 1) => { const s = 0.84 * h, ty = 112 - 49 * s; return { s, hy: ty - 56 * s, hr: 10 * s, sy: ty - 38 * s, sl: x - 13 * s, sr: x + 13 * s }; };
const hnd = (x: number, y: number, r = 3) => circle(x, y, r, C.skin, C.ink, 1.2);
/** An arm that starts at the shoulder (side −1 = picture-left, 1 = picture-right) and ends in a hand at (tx, ty). */
const reach = (x: number, h: number, side: -1 | 1, tx: number, ty: number) => { const q0 = geo(x, h); return all(arm(side < 0 ? q0.sl : q0.sr, q0.sy, tx, ty), hnd(tx, ty, 3 * Math.max(0.7, h))); };
const fig = (x: number, top: string, mood: Mood = 'smile', more: Partial<Build> = {}) => F({ x, top, mood, ...more });
/** Small head-and-shoulders person (for groups); mood smile | frown | flat | laugh. */
const mini = (x: number, y: number, col: string, mood: 'smile' | 'frown' | 'flat' | 'laugh' = 'smile', s = 1, long = false) => g(`translate(${x} ${y}) scale(${s})`, long ? path('M-8 -6 C-9 6 9 6 8 -6 Z', C.hair, null) : '', path('M-10 16 C-10 4 10 4 10 16 Z', col, C.ink, 1.4), circle(0, -6, 7.5, C.skin, C.ink, 1.4), path('M-7.5 -8 C-7.5 -16 7.5 -16 7.5 -8 C4 -11 -4 -11 -7.5 -8 Z', C.hair, null),
  mood === 'laugh' ? path('M-4 -6 Q-2.6 -8.4 -1.2 -6 M1.2 -6 Q2.6 -8.4 4 -6', 'none', C.ink, 1) : all(circle(-2.6, -6, 1, C.ink, null), circle(2.6, -6, 1, C.ink, null)),
  mood === 'smile' || mood === 'laugh' ? path('M-2.6 -2.6 Q0 -0.6 2.6 -2.6', 'none', C.ink, 1.1) : mood === 'flat' ? line('M-2.4 -2 L2.4 -2', C.ink, 1.1) : path('M-2.6 -1.4 Q0 -3.4 2.6 -1.4', 'none', C.ink, 1.1));
/** Up-and-down marks beside a head: the person nods. */
const nodM = (x: number, h = 1) => { const q0 = geo(x, h); return path(`M${f1(x - q0.hr - 4)} ${f1(q0.hy - 6)} q-2.6 6 0 12 M${f1(x + q0.hr + 4)} ${f1(q0.hy - 6)} q2.6 6 0 12`, 'none', HL, 1.5); };
/** Side-to-side marks beside a head: the person shakes the head. */
const shakeM = (x: number, h = 1) => { const q0 = geo(x, h); return path(`M${f1(x - q0.hr - 9)} ${f1(q0.hy - 2)} q3 -3 6 0 M${f1(x + q0.hr + 3)} ${f1(q0.hy - 2)} q3 -3 6 0 M${f1(x - q0.hr - 9)} ${f1(q0.hy + 3)} q3 -3 6 0 M${f1(x + q0.hr + 3)} ${f1(q0.hy + 3)} q3 -3 6 0`, 'none', HL, 1.5); };
const tie = (x: number, h = 1) => { const q0 = geo(x, h); return path(`M${f1(x - 1.6)} ${f1(q0.sy - 2)} L${f1(x + 1.6)} ${f1(q0.sy - 2)} L${f1(x + 2.4)} ${f1(q0.sy + 10 * h)} L${x} ${f1(q0.sy + 13 * h)} L${f1(x - 2.4)} ${f1(q0.sy + 10 * h)} Z`, RED, C.ink, 1); };

// ── Speech ───────────────────────────────────────────────────────────
/** Speech bubble centred on (cx, cy) whose tail points to (tx, ty). */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '', fill: string = C.white, stroke: string = C.ink) => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2;
  let a: number[], b: number[], a2: number[], b2: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, inw = tx < L ? 1.6 : -1.6, by = Math.max(Tp + 6, Math.min(B - 6, ty)); a = [e, by - 4.5]; b = [e, by + 4.5]; a2 = [e + inw, by - 3.6]; b2 = [e + inw, by + 3.6]; }
  else { const e = ty > cy ? B : Tp, inw = ty > cy ? -1.6 : 1.6, bx = Math.max(L + 7, Math.min(R - 7, tx)); a = [bx - 5, e]; b = [bx + 5, e]; a2 = [bx - 4, e + inw]; b2 = [bx + 4, e + inw]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, stroke, 1.5), rect(L, Tp, w, h, fill, 6, stroke, 1.5), path(`M${a2[0]} ${a2[1]} L${tx} ${ty} L${b2[0]} ${b2[1]} Z`, fill, null), inner);
};
/** Bubble beside the head of the figure at x (side 1 = right of the head, −1 = left); f draws the content at the bubble centre. */
const sb = (x: number, h: number, side: 1 | -1, w: number, hh: number, f: (cx: number, cy: number) => Svg, dx = 0, dy = 0) => { const k = geo(x, h), cx = x + side * (k.hr + 6 + w / 2) + dx, cy = k.hy - 8 + dy; return say(cx, cy, w, hh, x + side * (k.hr + 1), k.hy, f(cx, cy)); };
/** Thought cloud beside a head (side as in sb). */
const tb = (x: number, h: number, side: 1 | -1, w: number, f: (cx: number, cy: number) => Svg, dx = 0, dy = 0) => { const k = geo(x, h), cx = x + side * (k.hr + 8 + w / 2) + dx, cy = k.hy - 6 + dy; return all(ellipse(cx, cy, w / 2, 12, C.white, C.ink, 1.6), circle(x + side * (k.hr + 5), k.hy - 4, 2.4, C.white, C.ink, 1.1), circle(x + side * (k.hr + 2), k.hy + 1, 1.6, C.white, C.ink, 1), f(cx, cy)); };

// ── Icons (about 12 units) ───────────────────────────────────────────
const q = (x: number, y: number, sz = 13, col: string = C.navy) => T(x, y + sz * 0.36, '?', sz, col);
const ex = (x: number, y: number, sz = 13, col: string = HL) => T(x, y + sz * 0.36, '!', sz, col);
const dots = (x: number, y: number, col: string = C.grey) => all(circle(x - 5, y, 1.5, col, null), circle(x, y, 1.5, col, null), circle(x + 5, y, 1.5, col, null));
const face = (x: number, y: number, r: number, m: 'smile' | 'sad' | 'flat' | 'grin' = 'smile', col: string = C.yellow) => all(circle(x, y, r, col, C.ink, 1.1), circle(x - r * 0.36, y - r * 0.22, r * 0.13, C.ink, null), circle(x + r * 0.36, y - r * 0.22, r * 0.13, C.ink, null),
  m === 'flat' ? line(`M${x - r * 0.4} ${y + r * 0.38} L${x + r * 0.4} ${y + r * 0.38}`, C.ink, 1.1)
    : m === 'sad' ? path(`M${x - r * 0.42} ${y + r * 0.55} Q${x} ${y + r * 0.15} ${x + r * 0.42} ${y + r * 0.55}`, 'none', C.ink, 1.1)
      : path(`M${x - r * 0.46} ${y + r * 0.2} Q${x} ${y + r * (m === 'grin' ? 0.85 : 0.68)} ${x + r * 0.46} ${y + r * 0.2}${m === 'grin' ? ' Z' : ''}`, m === 'grin' ? '#c84a4a' : 'none', C.ink, 1.1));
const thumb = (x: number, y: number, s = 1, down = false) => g(`translate(${x} ${y}) scale(${s} ${down ? -s : s})`, rect(-4.4, -11, 4.4, 10, C.skin, 2.2, C.ink, 1.1), rect(-5, -3, 11, 10, C.skin, 3, C.ink, 1.1), line('M-0.6 0.4 L5.4 0.4 M-0.6 3.4 L5.4 3.4', C.ink, 0.8), rect(-8, -2.4, 3.2, 9, C.navy, 1, C.ink, 0.9));
const cross = (x: number, y: number, s = 1, col: string = RED) => line(`M${x - 5 * s} ${y - 5 * s} L${x + 5 * s} ${y + 5 * s} M${x + 5 * s} ${y - 5 * s} L${x - 5 * s} ${y + 5 * s}`, col, 2.4 * s);
const check = (x: number, y: number, s = 1, col: string = C.green) => checkIcon(x, y, s, col);
const okB = (x: number, y: number, r = 8) => all(circle(x, y, r, C.green, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, r * 0.22));
const palm = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, ...[-4.6, -1.6, 1.4, 4.4].map((d, i) => rect(d - 1.3, -9 + Math.abs(i - 1.5) * 1.2, 2.6, 9, C.skin, 1.3, C.ink, 0.9)), path('M-5.5 -1 L5.5 -1 L5 5 C4 8 -4 8 -5 5 Z', C.skin, C.ink, 1), path('M-5.4 1 L-9 -3 C-10 -4 -11 -2 -10 -1 L-5 5', C.skin, C.ink, 1));
const idea = (x: number, y: number, s = 1, lit = true) => g(`translate(${x} ${y}) scale(${s})`, lit ? path('M-9 -9 l-3 -3 M0 -12 l0 -4 M9 -9 l3 -3', 'none', C.gold, 1.6) : '', circle(0, -2, 6, lit ? C.yellow : C.grey2, C.ink, 1.2), rect(-3, 3.5, 6, 4.5, C.grey, 1, C.ink, 1));
const lines = (x: number, y: number, w: number, n = 3, col: string = C.grey) => all(...Array.from({ length: n }, (_, i) => line(`M${x - w / 2} ${y + i * 4.4} L${x + w / 2 - (i === n - 1 ? w * 0.35 : 0)} ${y + i * 4.4}`, col, 1.6)));
const clock = (x: number, y: number, r = 8, hAng = 300, mAng = 0, fill: string = C.white) => { const p = (a: number, l: number) => `${f1(x + Math.sin((a * Math.PI) / 180) * l)} ${f1(y - Math.cos((a * Math.PI) / 180) * l)}`; return all(circle(x, y, r, fill, C.ink, 1.4), line(`M${x} ${y} L${p(hAng, r * 0.5)} M${x} ${y} L${p(mAng, r * 0.78)}`, C.ink, 1.3)); };
/** Clock with a filled sector from 12 o'clock over `frac` of the face (time spent). */
const clockSpan = (x: number, y: number, r: number, frac: number, col: string = HL) => { const a = frac * 2 * Math.PI, ex2 = x + Math.sin(a) * r, ey = y - Math.cos(a) * r; return all(circle(x, y, r, C.white, C.ink, 1.6), path(`M${x} ${y} L${x} ${y - r} A${r} ${r} 0 ${frac > 0.5 ? 1 : 0} 1 ${f1(ex2)} ${f1(ey)} Z`, col, null), circle(x, y, r, 'none', C.ink, 1.6), line(`M${x} ${y} L${x} ${y - r * 0.8} M${x} ${y} L${f1(ex2 * 0.8 + x * 0.2)} ${f1(ey * 0.8 + y * 0.2)}`, C.ink, 1.4)); };
const mag = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, circle(0, 0, 8, 'rgba(220,240,252,0.7)', C.ink, 2), line('M5.6 5.6 L12 12', C.ink, 3));
const coinI = (x: number, y: number, r = 5) => coin(x, y, r);
const coins = (x: number, y: number, n = 3, r = 5) => all(...Array.from({ length: n }, (_, i) => all(ellipse(x, y - i * 3, r, r * 0.45, C.gold, C.ink, 1.1))));
const upA = (x: number, y: number, col: string = RED, l = 10) => arrow(x, y + l / 2, x, y - l / 2, col, 2);
const downA = (x: number, y: number, col: string = C.green, l = 10) => arrow(x, y - l / 2, x, y + l / 2, col, 2);
const tag = (x: number, y: number, s = 1, col: string = C.yellow, rot = 0, inner: Svg = '') => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, path('M-12 -7 L8 -7 L14 0 L8 7 L-12 7 Z', col, C.ink, 1.4), circle(7, 0, 1.8, C.white, C.ink, 1), inner);
/** A sheet of paper with text lines; `marks` in the sheet's own coordinates (−14…14, −18…18). */
const doc = (x: number, y: number, s = 1, marks: Svg = '', n = 5, col: string = C.grey2) => g(`translate(${x} ${y}) scale(${s})`, rect(-14, -18, 28, 36, C.white, 2, C.ink, 1.6), ...Array.from({ length: n }, (_, i) => line(`M-9 ${-11 + i * 6} L9 ${-11 + i * 6}`, col, 2)), marks);
const chart = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M-10 8 L10 8 M-10 8 L-10 -10', C.ink, 1.4), rect(-7, 0, 4, 8, C.sky, 0, null), rect(-1, -5, 4, 13, C.green, 0, null), rect(5, -2, 4, 10, C.orange, 0, null));
const book = (x: number, y: number, s = 1, col: string = C.navy) => g(`translate(${x} ${y}) scale(${s})`, rect(-7, -9, 14, 18, col, 1.5, C.ink, 1.2), rect(-7, -9, 3, 18, '#1f3354', 0.5, null), rect(-2, -5, 7, 3, C.white, 0.5, null));
const train = (x: number, y: number, s = 1, col: string = C.sky) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 6 L-12 -4 C-12 -8 -8 -8 -4 -8 L10 -8 C12 -8 13 -6 13 -4 L13 6 Z', col, C.ink, 1.2), rect(-9, -5, 6, 5, C.white, 1, null), rect(-1, -5, 6, 5, C.white, 1, null), rect(7, -5, 4, 5, C.white, 1, null), circle(-7, 7, 2, C.dark, null), circle(8, 7, 2, C.dark, null));
const bus = (x: number, y: number, s = 1, col: string = C.red) => g(`translate(${x} ${y}) scale(${s})`, rect(-11, -7, 22, 13, col, 2.4, C.ink, 1.2), rect(-9, -5, 6, 5, '#bfe3f5', 1, null), rect(-1.5, -5, 6, 5, '#bfe3f5', 1, null), circle(-6, 6.5, 2.2, C.dark, null), circle(6, 6.5, 2.2, C.dark, null));
const car = (x: number, y: number, s = 1, col: string = C.green) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 4 L-12 -1 L-7 -2 L-4 -7 L5 -7 L8 -2 L12 -1 L12 4 Z', col, C.ink, 1.2), path('M-3 -6 L-1 -3 L5 -3 L4 -6 Z', '#bfe3f5', null), circle(-6, 4.5, 2.4, C.dark, null), circle(6, 4.5, 2.4, C.dark, null));
const walker = (x: number, y: number, s = 1, col: string = C.navy) => g(`translate(${x} ${y}) scale(${s})`, circle(1, -8, 2.4, col, null), line('M1 -5 L0 2 M0 2 L-3 8 M0 2 L3 8 M0.6 -3 L-3 0 M0.6 -3 L4 -1', col, 1.8));
const house = (x: number, y: number, s = 1, col: string = C.yellow, old = false) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 -2 L0 -13 L12 -2 Z', old ? '#9a6a5a' : C.red, C.ink, 1.3), rect(-10, -2, 20, 14, col, 1, C.ink, 1.3), rect(-3, 4, 6, 8, C.brown, 0.5, C.ink, 1), old ? line('M5 0 L7 4 L5 7 M-8 2 L-6 5', C.ink, 0.9) : '');
const iceCream = (x: number, y: number, s = 1, col: string = C.pink) => g(`translate(${x} ${y}) scale(${s})`, path('M-5 -1 L5 -1 L0 11 Z', C.tan, C.ink, 1), line('M-3 2 L2 6 M2 1 L-1 6', '#a0673d', 0.7), circle(0, -4, 5.4, col, C.ink, 1));
const umbrella = (x: number, y: number, s = 1, col: string = C.purple) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 0 C-12 -12 12 -12 12 0 C9 -2 7 -2 4 0 C1 -2 -1 -2 -4 0 C-7 -2 -9 -2 -12 0 Z', col, C.ink, 1.2), line('M0 0 L0 12 C0 15 -4 15 -4 12', C.ink, 1.4));
const plateI = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, ellipse(0, 2, 10, 4, C.white, C.ink, 1.2), path('M-6 1 C-6 -5 6 -5 6 1 Z', '#8a9a4a', C.ink, 1), circle(-2, -2, 1.4, '#c84a3a', null));
const rainLines = (pts: Array<[number, number]>, col: string = '#5aa7e8') => all(...pts.map(([x, y]) => line(`M${x} ${y} l-2 6`, col, 1.6)));
const sign = (x: number, _y: number, inner: Svg, col: string, top = 30) => all(line(`M${x} 112 L${x} ${top + 10}`, C.brown, 3), rect(x - 12, top - 10, 24, 20, col, 3, C.ink, 1.6), inner);
const easel = (x: number, y: number, w: number, h: number, inner: Svg = '') => all(line(`M${x - w / 2 + 6} ${y + h} L${x - w / 2 + 2} 112 M${x + w / 2 - 6} ${y + h} L${x + w / 2 - 2} 112 M${x} ${y + h} L${x} 108`, C.brown, 2.4), rect(x - w / 2, y, w, h, C.white, 2, C.ink, 1.8), inner);
const meIcon = (x: number, y: number, col: string = C.orange, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-6 7 C-6 2 6 2 6 7 Z', col, C.ink, 1), circle(0, -1.5, 3.6, C.skin, C.ink, 1), path('M-3.6 -2.5 C-3.6 -6.4 3.6 -6.4 3.6 -2.5 C2 -4 -2 -4 -3.6 -2.5 Z', C.hair, null));
const gauge = (x: number, y: number, r: number, v: number) => { const a = Math.PI * (1 - (v + 1) / 2), nx = x + Math.cos(a) * r * 0.8, ny = y - Math.sin(a) * r * 0.8; return all(path(`M${x - r} ${y} A${r} ${r} 0 0 1 ${f1(x - r * 0.5)} ${f1(y - r * 0.866)}`, 'none', RED, 4), path(`M${f1(x - r * 0.5)} ${f1(y - r * 0.866)} A${r} ${r} 0 0 1 ${f1(x + r * 0.5)} ${f1(y - r * 0.866)}`, 'none', C.yellow, 4), path(`M${f1(x + r * 0.5)} ${f1(y - r * 0.866)} A${r} ${r} 0 0 1 ${x + r} ${y}`, 'none', C.green, 4), line(`M${x} ${y} L${f1(nx)} ${f1(ny)}`, C.ink, 2), circle(x, y, 2.4, C.ink, null), face(x - r - 6, y - 2, 4.4, 'sad', '#f6b0a0'), face(x + r + 6, y - 2, 4.4, 'smile', '#bfe8b0')); };
const pie = (x: number, y: number, r: number, frac: number, col: string = C.green, rest: string = C.grey2) => { const a = frac * 2 * Math.PI, ex2 = x + Math.sin(a) * r, ey = y - Math.cos(a) * r; return all(circle(x, y, r, rest, C.ink, 1.4), path(`M${x} ${y} L${x} ${y - r} A${r} ${r} 0 ${frac > 0.5 ? 1 : 0} 1 ${f1(ex2)} ${f1(ey)} Z`, col, C.ink, 1.2)); };
const scales = (x: number, y: number, s = 1, tilt = 0, l: Svg = '', r: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, line('M0 -26 L0 22 M-12 22 L12 22', C.ink, 2.4), g(`rotate(${tilt} 0 -24)`, line('M-26 -24 L26 -24', C.ink, 2.4), line('M-26 -24 L-32 -8 M-26 -24 L-20 -8 M26 -24 L20 -8 M26 -24 L32 -8', C.ink, 1), path('M-34 -8 C-34 -2 -18 -2 -18 -8 Z', C.gold, C.ink, 1.2), path('M18 -8 C18 -2 34 -2 34 -8 Z', C.gold, C.ink, 1.2), g('translate(-26 -14)', l), g('translate(26 -14)', r)), circle(0, -26, 2.4, C.gold, C.ink, 1));
const podium = (x: number, w = 30, h = 14) => all(rect(x - w / 2, 112 - h, w, h, C.tan, 2, C.ink, 1.6), line(`M${x - w / 2} ${116 - h} L${x + w / 2} ${116 - h}`, '#a0673d', 1.2));
const table = (y = 84, x1 = 8, x2 = 112) => all(rect(x1, y, x2 - x1, 6, C.tan, 2, C.ink, 1.8), line(`M${x1 + 8} ${y + 6} L${x1 + 8} 112 M${x2 - 8} ${y + 6} L${x2 - 8} 112`, C.brown, 3));
const painting = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-18, -13, 36, 26, '#c8925a', 2, C.ink, 1.6), rect(-14, -9, 28, 18, '#eaf4fb', 1, null), circle(-6, -2, 4, C.yellow, null), path('M-14 9 L-4 0 L4 6 L9 2 L14 9 Z', C.green, null), path('M6 -7 C10 -9 12 -5 10 -3', 'none', RED, 1.4));
const eyeLine = (x1: number, y1: number, x2: number, y2: number, col: string = C.grey) => line(`M${x1} ${y1} L${x2} ${y2}`, col, 1.2, '2 3');

const thermo = (x: number, y: number, s = 1, lvl = 0.6) => g(`translate(${x} ${y}) scale(${s})`, rect(-2.6, -11, 5.2, 16, C.white, 2.6, C.ink, 1.1), rect(-1.2, 3 - 13 * lvl, 2.4, 13 * lvl, RED, 1, null), circle(0, 7, 4, RED, C.ink, 1.1));
